   "answer": "B",
   "analysis": "根据题干“···2014年占···比重高于上年水平的包括”可判定本题为两期比重问题。\n方法一：根据两期比重结论，部分增长率img/formula-e71b78de2366f987.webp大于总体增长率img/formula-309dfc725f26f1b5.webp则比重同比上升，即高于上年水平。定位表格可知2013年、2014年中国旅游业总收入和在线旅游收入各部分的相关数据。利用公式“增长率img/formula-c7d648595ca9f80a.webp”可得，总体增长率img/formula-309dfc725f26f1b5.webp即中国旅游业总收入增长率img/formula-3ed08aad5644046c.webpimg/formula-74421daac21d65b5.webpimg/formula-2e25b95f130e9fdf.webpimg/formula-0c793ae1bc0b6efa.webpimg/formula-d7c844fbd15629b2.webp；img/formula-b1929dc50f392290.webp增长率img/formula-b69d747971c469ae.webp即在线交通预订收入增长率img/formula-ac54f013d5e9c62b.webpimg/formula-74421daac21d65b5.webpimg/formula-5b5b9b2111942d50.webpimg/formula-f6afec456dec9303.webp；img/formula-c02a18b84ccb2c15.webp增长率img/formula-deaf20729e33ff5e.webp即在线住宿预订收入增长率img/formula-a74f064cf07bf471.webpimg/formula-fa85d7d31053dcac.webpimg/formula-5184fff1fd1a6a15.webp；img/formula-fdb7649bb8816cbd.webp增长率img/formula-41d9fbd396998117.webp即在线度假旅游预订收入增长率img/formula-f7124b729fcc0e6b.webpimg/formula-74421daac21d65b5.webpimg/formula-78ba9548d61519d2.webpimg/formula-1d53cfa5f073512e.webp。因此，满足条件的有在线交通预订，img/formula-b69d747971c469ae.webpimg/formula-0e40b874513a7238.webpimg/formula-24bb221293f88a08.webpimg/formula-71c4bedd785263f1.webpimg/formula-076643f151903a38.webp；在线住宿预订，img/formula-a88ce5e9bf382674.webp；在线度假旅游预订，img/formula-9648d9d2e823fcec.webp。\n方法二：根据表格中2013年、2014年中国旅游业总收入和在线旅游收入各部分的相关数据，利用公式“比重img/formula-cfd5a354bfa532c4.webp”可得，2013年、2014年在线交通预订收入占中国旅游业总收入的比重分别img/formula-204290938362d80a.webpimg/formula-d325b43f9d56225f.webpimg/formula-8bbd50c48a0a2c55.webp、img/formula-56f8441712aba32c.webpimg/formula-9fac0604d2a1c3bf.webpimg/formula-a4b5c9a3465e7b53.webp，img/formula-a8096fa7c3116ca4.webpimg/formula-b3db685fc696009c.webpimg/formula-24bb221293f88a08.webpimg/formula-2ff75999d3d627c1.webpimg/formula-3de3a0447b190bc1.webp，即比重高于上年水平；\n2013年、2014年在线住宿预订收入占中国旅游业总收入的比重分别img/formula-96ba8b8c3cb085b7.webpimg/formula-627921baa386c0fc.webpimg/formula-c64beb92a0451682.webp、img/formula-207abe48b7e72926.webpimg/formula-b073888f536ed6c0.webpimg/formula-d3dceb6f62ab1c9d.webp，img/formula-a8096fa7c3116ca4.webpimg/formula-36650746480be0f6.webpimg/formula-24bb221293f88a08.webpimg/formula-2ff75999d3d627c1.webpimg/formula-4de51f80f9f9abcc.webp，即比重高于上年水平；\n2013年、2014年在线度假旅游预订收入占中国旅游业总收入的比重分别img/formula-b007a843af6638a9.webpimg/formula-ea84ed608dfa6cbb.webpimg/formula-88344028285395f3.webp、img/formula-6f20eed451bf05c3.webpimg/formula-d23aa367ed3b21e1.webpimg/formula-b622d77cbad89c85.webp，则img/formula-6b05d063e372ccf6.webp，即比重高于上年水平。\n故满足条件的有在线交通预订、在线住宿预订、在线度假旅游预订。\n故正确答案为B。",
