   "answer": "C",
   "analysis": "根据题干“······同比增量的变化趋势”，可判定本题为增长量比较问题。\nA项：定位表格第四列数据可得：“2013年~2018年在线住宿预订收入依次为412.10亿元、547.45亿元、862.57亿元、1251.42亿元、1586.19亿元、1881.49亿元”，根据公式：增长量=现期量-基期量，则2014-2018年在线住宿预订收入同比增量依次为2014年：547.45-412.10img/formula-2ee93fe9e223e4c6.webp547-412=135亿元、2015年：862.57-547.45img/formula-2ee93fe9e223e4c6.webp863-547=316亿元、2016年：1251.42-862.57img/formula-2ee93fe9e223e4c6.webp1251-863=388亿元；2017年：1586.19-1251.42img/formula-2ee93fe9e223e4c6.webp1586-1251=335亿元；2018年：1881.49-1586.19img/formula-2ee93fe9e223e4c6.webp1881-1586=295亿元。2017年比2015年增长量大，即折线图中第4个点应比第2个点高，与题干折线图矛盾，排除A项。\nB项：定位表格第二列数据可得：“2013年~2018年旅游业总体收入依次为2.95万亿元、3.38万亿元、4.13万亿元、4.69万亿元、5.40万亿元、5.97万亿元”，则2014-2018年旅游业总体收入同比增量依次为2014年：3.38-2.95=0.43万亿元、2015年：4.13-3.38=0.75万亿元、2016年：4.69-4.13=0.56万亿元、2017年：5.40-4.69=0.71万亿元、2018年：5.97-5.40=0.57万亿元。2015年增长量最大，即折线图中第2个点应该最高，与题干折线图矛盾，排除B项。\nC项：定位表格第五列数据可得：“2013年~2018年在线度假旅游预订收入依次为244.20亿元、347.58亿元、549.97亿元、757.40亿元、947.47亿元、1051.81亿元”，则2014-2018年在线度假旅游预订收入同比增量依次为2014年：347.58-244.20img/formula-2ee93fe9e223e4c6.webp348-244=104亿元、2015年：549.97-347.58img/formula-2ee93fe9e223e4c6.webp550-348=202亿元、2016年：757.40-549.97img/formula-2ee93fe9e223e4c6.webp757-550=207亿元、2017年：947.47-757.40img/formula-2ee93fe9e223e4c6.webp947-757=190亿元、2018年：1051.81-947.47img/formula-2ee93fe9e223e4c6.webp1052-947=105亿元。满足题干折线图趋势。\nD项：定位表格第三列数据可得：“2013年~2018年在线交通预订收入依次为1519.67亿元、2271.57亿元、3325.15亿元、5385.42亿元、6389.65亿元、6820.95亿元”，则2014-2018年在线交通预订收入同比增量依次为2014年：2271.57-1519.67img/formula-2ee93fe9e223e4c6.webp2272-1520=752亿元、2015年：3325.15-2271.57img/formula-2ee93fe9e223e4c6.webp3325-2272=1053亿元、2016年：5385.42-3325.15img/formula-2ee93fe9e223e4c6.webp5385-3325=2060亿元、2017年：6389.65-5385.42img/formula-2ee93fe9e223e4c6.webp6390-5385=1005亿元、2018年：6820.95-6389.65img/formula-2ee93fe9e223e4c6.webp6821-6390=431亿元。2018年增长量较2014年小很多，即折线图中第5个点应比第1个点低很多，与题干折线图矛盾，排除D项。\n故正确答案为C。",
